// Round-3 margin part A: SC, MN, NJ, NM, ID — push every page to ~950+ unique 5-grams.
import { readFileSync, writeFileSync } from "node:fs";
const path = "data/city-pages.json";
const data = JSON.parse(readFileSync(path, "utf8"));
const get = (st, sl) => data.find((c) => c.state === st && c.slug === sl);
const A = (st, sl, add) => {
  const e = get(st, sl);
  if (!add) return;
  for (const [k, v] of Object.entries(add)) {
    if (k === "h") e.heroIntro += " " + v;
    else if (k === "l") e.premium.heroLead += ", with " + v;
    else if (k === "s0") e.services[0].text += " " + v;
    else if (k === "s1") e.services[1].text += " " + v;
    else if (k === "s2") e.services[2].text += " " + v;
    else if (k === "d0") e.destinations[0].text += " " + v;
    else if (k === "d1") e.destinations[1].text += " " + v;
    else if (k === "d2") e.destinations[2].text += " " + v;
    else if (k === "f0") e.faqs[0].a += " " + v;
    else if (k === "f1") e.faqs[1].a += " " + v;
    else if (k === "f2") e.faqs[2].a += " " + v;
  }
};

